package net.dogpoo.api;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
import org.apache.ibatis.datasource.unpooled.UnpooledDataSource;import org.apache.ibatis.mapping.Environment;import org.apache.ibatis.session.*;import org.apache.ibatis.transaction.jdbc.JdbcTransactionFactory;
import net.dogpoo.api.core.weaver.mapper.*;
@EnabledIfEnvironmentVariable(named="WEAVER_POLICY_TEST_URL",matches=".+")
class WeaverPolicyIntegrationTest {
 SqlSessionFactory factory;
 @BeforeEach void setup(){var config=new Configuration(new Environment("test",new JdbcTransactionFactory(),new UnpooledDataSource("org.mariadb.jdbc.Driver",System.getenv("WEAVER_POLICY_TEST_URL"),"root","local-split-test")));config.addMapper(WeaverPolicyMapper.class);config.addMapper(WeaverWorkspaceMapper.class);factory=new SqlSessionFactoryBuilder().build(config);}
 @Test void expiryImmediatelyChangesEffectivePlanAndCancellationKeepsPeriod(){try(var s=factory.openSession()){var p=s.getMapper(WeaverPolicyMapper.class);p.subscribe("existing","pro",LocalDateTime.now(ZoneOffset.UTC).plusDays(2),false);assertEquals("pro",p.plan("space").get("code"));String end=(String)p.subscription("existing").get("periodEnd");p.cancel("existing",true);assertEquals(end,p.subscription("existing").get("periodEnd"));assertEquals("pro",p.plan("space").get("code"));p.subscribe("existing","pro",LocalDateTime.now(ZoneOffset.UTC).minusSeconds(1),true);assertEquals("free",p.plan("space").get("code"));assertEquals(0,p.cancel("existing",false));s.rollback();}}
 @Test void existingAccountsNeverAutoProvisionAndNewAccountsProvisionOnce()throws Exception{try(var s=factory.openSession()){var p=s.getMapper(WeaverPolicyMapper.class);var w=s.getMapper(WeaverWorkspaceMapper.class);assertEquals(1,p.provisioned("existing"));assertEquals(0,w.ensure("existing"));String id=UUID.randomUUID().toString();s.getConnection().createStatement().executeUpdate("INSERT INTO WEAVER_USER_ACCOUNT(id,email) VALUES('"+id+"','new@test.invalid')");assertEquals(1,w.ensure(id));assertEquals(1,p.provision(id));s.getConnection().createStatement().executeUpdate("DELETE FROM WEAVER_ACCOUNT_WORKSPACE WHERE user_id='"+id+"'");assertEquals(0,w.ensure(id));s.rollback();}}
 @Test void defaultLimitsRemainUnsetExceptFreeEditorCountAndAdminAuditPersists(){try(var s=factory.openSession()){var p=s.getMapper(WeaverPolicyMapper.class);var free=p.plans().stream().filter(r->"free".equals(r.get("code"))).findFirst().orElseThrow();assertEquals(2,((Number)free.get("editor_limit")).intValue());assertEquals(2,((Number)free.get("owned_limit")).intValue());assertNull(free.get("document_limit"));assertNull(free.get("storage_limit"));assertEquals("user",p.platformRole("existing"));p.platformRoleSet("existing","admin");assertEquals(1,p.admins());p.audit("existing","test","space","{}");assertFalse(p.auditList().isEmpty());s.rollback();}}
 @Test void oneAccountSubscriptionAppliesToEveryOwnedSpaceAndCooldownHasRollingBoundary()throws Exception{try(var s=factory.openSession()){var p=s.getMapper(WeaverPolicyMapper.class);s.getConnection().createStatement().executeUpdate("INSERT INTO WEAVER_ACCOUNT_WORKSPACE(user_id,owner_id,name) VALUES('second','existing','Second')");p.subscribe("existing","standard",LocalDateTime.now(ZoneOffset.UTC).plusDays(2),false);assertEquals("standard",p.plan("space").get("code"));assertEquals("standard",p.plan("second").get("code"));assertEquals(10,((Number)p.accountPlan("existing").get("owned_limit")).intValue());p.created("existing");assertEquals(1,p.coolingDown("existing"));s.getConnection().createStatement().executeUpdate("UPDATE WEAVER_ACCOUNT_CREATION SET last_created_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 24 HOUR) WHERE user_id='existing'");s.clearCache();assertEquals(0,p.coolingDown("existing"));p.free("existing");assertEquals("free",p.plan("space").get("code"));assertEquals("free",p.plan("second").get("code"));s.rollback();}}
}
